// ❌ OLD: Time-based ISR can display stale data for up to 60 seconds
// after an administrative price update.
export default async function ProductsPage() {
  const res = await fetch('https://api.example.com/products', {
    next: { revalidate: 60 }
  });
  const products = await res.json();

  return <div>{products.map((p: any) => <p key={p.id}>{p.name}</p>)}</div>;
}

